<script setup lang="ts"> import { computed } from 'vue'; import { useRouter } from 'vue-router'; import { auth, logout } from './auth'; const router = useRouter(); const isCustomer = computed(() => auth.user?.role === 'CUSTOMER'); function exit(){ logout(); router.push('/login'); } </script>
<template><v-app><v-app-bar color="primary" density="comfortable"><v-app-bar-title>Chevymania</v-app-bar-title><template v-if="auth.user"><v-btn to="/" variant="text">Inicio</v-btn><v-btn v-if="!isCustomer" to="/customers" variant="text">Clientes</v-btn><v-btn to="/orders" variant="text">{{ isCustomer ? 'Mis órdenes' : 'Órdenes' }}</v-btn><v-btn variant="text" @click="exit">Salir</v-btn></template></v-app-bar><v-main><v-container class="py-8"><router-view/></v-container></v-main></v-app></template>
